import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"GameWorld: Towards Standardized and Verifiable Evaluation of Multimodal Game Agents","description":"","frontmatter":{"title":"GameWorld: Towards Standardized and Verifiable Evaluation of Multimodal Game Agents","arxiv":"2604.07429","date":"2026-04-08","authors":"Mingyu Ouyang, Siyuan Hu, Kevin Qinghong Lin, Hwee Tou Ng, Mike Zheng Shou","categories":"cs.CV, cs.AI, cs.HC","topics":"多模态智能体, 游戏 benchmark, 具身评测","outline":[2,2]},"headers":[],"relativePath":"papers/2604.07429.md","filePath":"papers/2604.07429.md","lastUpdated":null}'),p={name:"papers/2604.07429.md"};function l(r,s,m,c,i,o){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="gameworld-towards-standardized-and-verifiable-evaluation-of-multimodal-game-agents" tabindex="-1">GameWorld: Towards Standardized and Verifiable Evaluation of Multimodal Game Agents <a class="header-anchor" href="#gameworld-towards-standardized-and-verifiable-evaluation-of-multimodal-game-agents" aria-label="Permalink to &quot;GameWorld: Towards Standardized and Verifiable Evaluation of Multimodal Game Agents&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2604.07429" target="_blank" rel="noreferrer">2604.07429</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-04-08</td></tr><tr><td><strong>作者</strong></td><td>Mingyu Ouyang, Siyuan Hu, Kevin Qinghong Lin, Hwee Tou Ng, Mike Zheng Shou</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.HC</td></tr><tr><td><strong>一句话</strong></td><td>用一个「推理时暂停游戏」的浏览器沙盒把延迟从分数里剥掉，再把 34 款游戏的操作接口归一成键鼠原语与确定性语义动作两条路径，并给 170 个任务各配一个从注入的 gameAPI 序列化状态直接读出的判定器，从而让多模态游戏智能体的成绩既可比又可复现。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>要让多模态大模型（MLLM）成为能在真实世界交互的通用智能体，论文点出三个当下仍未解决的困难：<strong>延迟</strong>、<strong>反馈稀疏</strong>、<strong>错误不可逆</strong>。这三条恰好都是静态问答式 benchmark 测不出来的——静态评测里模型想多久都行、每一步都有明确标签、答错了也不影响下一题。</p><p>视频游戏被认为是理想测试平台，因为它同时提供丰富的视觉观测和<strong>闭环交互</strong>，并要求细粒度感知、长时程规划和精确控制三者兼备；浏览器游戏尤其合适，因为轻量、机制多样、易重置。但论文指出，系统性评测这些能力目前被三件事卡住：<strong>异构的动作接口</strong>、<strong>实时交互中的延迟耦合</strong>、以及<strong>缺少基于结果的可验证判定</strong>。第一条的意思是每款游戏、每个 API 的操作方式都不一样，模型在游戏 A 上的分数和游戏 B 上的分数不可比，也无法区分「模型不会玩」和「模型不会操作」；第二条的意思是慢的模型等它动手时面对的已经是更难的局面，思考时间被混进了游戏能力；第三条的意思是判断任务是否完成往往靠 OCR、像素启发式或 VLM-as-judge，引入感知噪声，结果难验证、难复现、难诊断。</p><p>这件事的价值在于，如果不把接口和验证标准化，社区就无法判断游戏智能体的进步来自能力提升还是评测设置变化。论文的定位很明确：不是提出更强的智能体，而是提供一个标准化、可验证、可复现的评测框架。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文的对比表把十一个既有 benchmark 摆在一起，缺口一眼可见。</p><p><strong>静态问答类</strong>先出局：GameQA（30 款游戏、158 题）与 VideoGameQA（800+ 游戏、9 类任务）都不是交互式的，模型不需要承担自己动作的后果。</p><p><strong>交互式的那批</strong>问题各不相同。LMGame-Bench 用模块化 harness 探查感知、记忆、推理，但只有 6 款游戏 6 个任务，且是文本中心；BALROG 强调长时程但同样只有 6 款游戏、48 个任务，且非 vision-centric；VideoGame-Bench 把规模拉到 23 款却仍是<strong>启发式判分</strong>；Orak 覆盖 12 款游戏但<strong>把游戏状态预处理成文本</strong>再喂给模型，视觉这一环被绕开了；MCU 只做 Minecraft；V-MAGE 只有 5 款；NitroGen 没有语言条件任务；FlashAdventure 有 34 款 Flash 冒险游戏，但判分用的是 CUA-as-a-Judge。</p><p>于是论文把不足收敛成三条：<strong>动作接口异构</strong>（同一个点击，一个 API 写 <code>left_click(x,y)</code>、另一个写 <code>computer(action=&quot;click&quot;,coordinate=[x,y])</code>，抽象层级也不同）、<strong>实时交互中的延迟耦合</strong>（慢一步，角色已经掉下平台，思考时间被混进了游戏能力里）、<strong>判分依赖启发式或 VLM-as-judge</strong>（引入感知噪声，结果难验证、难复现、难诊断）。</p><p>论文同时点名了并行工作 GameVerse：它也采用语义加 GUI 的双动作空间，并加了基于失败轨迹的 reflect-and-retry，但判分仍然靠 VLM 量化 progress。这条对比说明作者认为自己真正的差异化不在双接口，而在<strong>判分来自游戏内部状态</strong>。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>不使用本文自身的贡献作前提，路径大致如下。</p><p>第一步是问：为什么已有的游戏智能体结果这么难解读？观察到的现象是同一个模型在不同游戏、不同论文里的表现差异巨大，而这些差异既可能来自模型能力，也可能来自&quot;这套接口对模型友不友好&quot;。要拆开这两者，就需要在<strong>同一批游戏上同时提供两种接口</strong>，让接口成为可控变量而非混杂因素。这直接导出了论文的两接口设计：直接发键鼠控制的 computer-use agent，与在语义动作空间中行动的通用多模态 agent。</p><p>第二步是问：为什么判定不可靠？从截图上判断「任务是否完成」本质上是一个视觉识别问题，会引入第二个模型的误差。如果能从游戏的内部状态直接读出结果，判定就变成确定性的。这要求游戏运行在一个可以被程序化访问状态的环境里，<strong>浏览器</strong>恰好满足：轻量、机制多样、易重置，还能注入 JavaScript 桥把内部变量暴露出来。论文明确把浏览器游戏的这三条属性写成了选型理由。</p><p>第三步是问：延迟怎么办？VideoGameBench 已经指出推理延迟主导了实时场景下的失败，并引入了 paused track。顺着这条线往下推：既然延迟是混杂因素，那就<strong>默认把游戏暂停</strong>，让所有模型面对完全相同的游戏动态，分数只反映决策质量；再把「不暂停」单独做成一个变体去研究延迟本身。这正是 GameWorld 与 GameWorld-RT 的分工。</p><p>第四步是问：一个 benchmark 怎么证明自己可信？跑一次拿到排名不够，因为交互式评测天然有随机性。要证明结论稳定，就得<strong>重复整个 benchmark 多次</strong>并展示方差。论文对四个 model-interface 组合各做了十次完整重跑，把这件事当作核心贡献之一而非附录细节。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>要让游戏智能体的分数可比，必须把三个混杂源同时钉死：<strong>智能体通过什么接口行动</strong>、<strong>它有多少时间思考</strong>、<strong>谁来判定它是否成功</strong>。接口用两套标准化路径替代每款游戏各自的操作方式；时间用「推理期间暂停游戏」直接消掉；判定用注入的 JavaScript 桥从游戏内部变量读出，不经过任何模型。三样都钉死之后，剩下的分数差异才真正归因于决策质量。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>环境与任务。</strong> 34 款浏览器游戏，覆盖 Runner、Arcade、Platformer、Puzzle、Simulation 五个 genre，共 170 个任务（平均每款 5 个）。genre 的选择对应不同能力：Runner 与 Arcade 要求持续时间压力下的高频反应与多目标跟踪，Platformer 要求物理感知的精确空间导航，Puzzle 测离散状态空间里的逻辑推理与长时程规划，Simulation 是开放式的多目标环境。每个任务是一条自然语言指令加一个量化目标，执行过程中不给中间提示，智能体只能从截图自行决策。</p><p><strong>两个指标。</strong> 成功率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">}</span></span></span></span> 与进度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，后者是从配置的起始分到目标分之间的归一化推进量，给未完成的 run 部分学分。两者最终按 run 取平均并以百分比报告：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">1</span><span class="mopen">[</span><span class="mord"><span class="mord"><span class="mord mathrm">status</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord texttt">success</span></span><span class="mclose">]</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">progress</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2175em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mord">.</span></span></span></span></span></p><p><strong>统一控制空间。</strong> 所有模型输出最终都被归一到一组原子事件：<code>mouse_move</code>、<code>mouse_down</code>、<code>mouse_up</code>、<code>key_down</code>、<code>key_up</code>、<code>scroll</code>、<code>wait</code>。每款游戏只暴露自己需要的子集。</p><p><strong>接口一：Computer-Use Agent。</strong> 直接发 <code>mouse_move(x,y)</code>、<code>left_click(x,y)</code>、<code>press_key(key)</code> 之类，同时承担策略决策和动作 grounding。强制每步恰好一个可执行动作（允许组合键），超出该游戏允许控制空间的调用（例如 OS 级 API）会被拒绝。</p><p><strong>接口二：Generalist Agent + Semantic Action Parsing。</strong> 模型输出 <code>move_forward()</code>、<code>action_jump()</code>、<code>weapon_fire()</code>、<code>no_op()</code> 这类语义函数，由<strong>每款游戏每个角色一个确定性 parser</strong> 映射成固定的底层交互命令。确定性这一点是设计要害：它消掉了 parser 侧的随机性，使两条接口的差异可以被干净归因。这里同样强制 action atomicity，禁止把多个语义上不同的决策打包成一个宏动作。</p><p><strong>共享 harness。</strong> 四段式固定 prompt 模板（<code>#Game Rules</code>、<code>#Role and Controls</code>、<code>#Task Instruction</code>、<code>#Output Format</code>），只换游戏相关内容；滚动式 context memory，每一轮记录 <code>user_prompt → screenshot → reasoning → action</code>，作为 Action History 前置到当前观测之前；语义动作与键鼠原语通过各家原生 function calling 注册成工具。</p><p><strong>沙盒。</strong> 每款游戏跑在独立浏览器实例里，严格循环「截图 → 查询模型 → 执行一个动作」。首次决策前和每次 reset 后有一个 readiness gate，等游戏报告 ready 或 playing 才开始，吸收掉加载和菜单阶段。<strong>推理期间游戏暂停</strong>是默认设置。支持配置游戏速度与确定性种子。</p><p><strong>判分。</strong> 给每款游戏注入结构化 JavaScript 桥，暴露序列化的 gameAPI 状态：生命周期状态、终局元数据，以及 score、level、坐标、生命数、金币、checkpoint 这类任务相关变量。全库共人工设计了 <strong>233 个任务相关状态字段</strong>，平均每款游戏 6.85 个。每一步 evaluator 读当前状态、从配置好的标量字段或多字段聚合中解析任务分，算出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span>。触发终局失败（例如生命耗尽）时环境自动 reset、智能体在同一步数预算下继续，并保留 run 内最好进度，避免一次早期失误把整轮清零。</p><p>一次完整流程：智能体拿到当前帧截图 → 在接口二下输出 <code>action_jump()</code> → 确定性 parser 映射成对应按键序列发给浏览器 → 游戏推进固定时长（通常 200–500 ms）→ evaluator 从 gameAPI 读出新的 score 与坐标并更新进度 → 下一步，直到达标、终局或用完 <strong>100 个动作</strong>的预算。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>设置。</strong> 13 个基座模型，评出 18 个 model-interface 组合（8 个 CUA + 10 个 Generalist）。闭源侧包括 Claude-Sonnet-4.6、Gemini-2.5-Computer-Use、Gemini-3-Flash-Preview、GLM-4.6V、GPT-5.2、Grok-4.1-Fast-Reasoning、Kimi-K2.5、OpenAI-Computer-Use、Qwen3-VL-Plus、Seed-1.8；开源侧是 Qwen3-VL-235B-A22B、Qwen3-VL-30B-A3B、UI-TARS-1.5-7B。所有模型在同一暂停协议、同一 harness、同一 verifier 下评测，每任务 100 个动作预算。</p><p><strong>当前模型离人类有多远？</strong> Generalist 侧最好的是 Gemini-3-Flash-Preview（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">41.9</span></span></span></span>），其后 GPT-5.2 40.6、Claude-Sonnet-4.6 39.3、Seed-1.8 39.0；CUA 侧最好的是 Seed-1.8（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">39.8</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">20.0</span></span></span></span>），Claude-Sonnet-4.6 紧随（38.3 / 19.4）。全体 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span></span></span></span> 落在 12.4–21.2% 区间。人类基线由两名计算机方向的研究生给出，同样限 100 个原始动作：未接触过这些游戏的 Novice 拿到 55.3 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span></span></span></span> / 64.1 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span>，事先学过规则并练过操作的 Expert 拿到 77.1 / 82.6。<strong>最好的智能体连 Novice 都差得远</strong>，而且差距主要体现在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span></span></span></span> 上（20 对 55）——模型能推进，但收不了尾。</p><p><strong>benchmark 本身可信吗？</strong> 对 Qwen3-VL-30B-A3B 与 Qwen3-VL-235B-A22B 的四个 model-interface 组合各做十次完整重跑：30B-CUA 12.7±1.2 / 30.9±1.1，30B-Generalist 12.5±1.3 / 30.7±1.1，235B-CUA 13.8±0.7 / 30.4±0.7，235B-Generalist 13.6±1.4 / 30.1±0.5。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 的标准差在 0.5–1.1 之间，聚合结论稳定；方差集中在 Hextris、Cubefield、Wordle、World&#39;s Hardest Game 2 这几款控制敏感或高难度的游戏上。作者据此划了一条解释边界：<strong>相邻系统之间的微小差距，在没有重跑证据时不应被当真</strong>。</p><p><strong>失败到底卡在哪一层？</strong> 作者按主导瓶颈把 34 款游戏编成五级课程：L1 基础控制与时机 grounding、L2 System-1 反应式控制、L3 System-2 空间导航、L4 符号推理与策略、L5 开放世界协调与管理。两条接口的雷达图形状相似：<strong>在 L4 与 L2 上最高，在 L1 与 L5 上急剧下跌</strong>。这个结果有点反直觉——模型在需要策略的离散推理和需要反应的高频控制上还行，反而在最简单的「看准了再按一下」和最开放的长时程协调上垮掉。</p><p><strong>实时到底难在哪？</strong> GameWorld-RT 不暂停环境。Qwen3-VL-235B-A22B 在 CUA 下 6.2 秒/步、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span></span></span></span> 17.1 / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 33.2，Generalist 下 6.4 秒/步、16.8 / 34.0；30B 快得多（CUA 2.4 秒/步、Generalist 3.4 秒/步），成绩为 15.6 / 33.0 与 15.6 / 32.9。<strong>更快并没有换来更高的分</strong>，作者据此说实时下推理速度与动作时机被更紧地耦合在一起。作者同时明确警告 RT 与暂停版的数字不可直接对比，因为 RT 下同样的动作预算对应更长的游戏时间。</p><p><strong>记忆是不是越多越好？</strong> 对 Qwen3-VL-235B-A22B 扫 memory rounds 0/1/2：Generalist 侧输入从 1278 涨到 3052 token、5.5 秒/步涨到 8.6 秒/步，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 从 30.0 微升到 30.6；CUA 侧输入从 1891 涨到 5627 token、7.2 涨到 12.8 秒/步，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 反而从 30.3 掉到 28.7。作者的解释是 CUA 的历史是无语义的底层动作序列，与截图联合解读困难，越长越是干扰。结论是记忆应被当作有选择的收益而非普遍有用的模块。</p><p><strong>动作有效性。</strong> 无效动作分两类：No-Tool-Call（根本没发出可执行工具调用，多因思考过长被截断或格式不合）与 Out-of-Space（发了调用但越界，例如在纯键盘游戏里调 <code>left_click</code>，或调用未注册的 <code>craft_a_workbench()</code>）。总体规律是长交互上下文下弱模型更容易忘掉可用动作空间。</p><p><strong>作者自陈的限制</strong>：每接入一个新环境都要单独设计指令集，动作空间与任务被紧耦合，限制了扩展性；把 Semantic Action Parsing 的生成与对齐自动化留给了未来工作。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：GameWorld 针对游戏智能体评测里的三个混杂源——异构动作接口、推理延迟、启发式判定——分别给出了双标准接口、推理时暂停游戏的浏览器沙盒，以及从注入的 gameAPI 状态直接读数的判定器（全库 233 个人工设计的状态字段）。34 款游戏、170 个任务、18 个 model-interface 组合，指标是成功率与归一化进度两条。最好的智能体 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 约 42（Gemini-3-Flash-Preview），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span></span></span></span> 全体只有 12.4–21.2%，而两名研究生里的 Novice 就有 55.3 / 64.1——差距主要在「收尾」而不在「推进」。十次完整重跑显示 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 标准差只有 0.5–1.1，作者据此声明相邻系统的微小差距不可当真。五级能力课程给出一个反直觉结论：模型在符号推理与高频反应上相对好，在最基础的时机 grounding 和最开放的长时程协调上最差。</p><p><strong>3 句话版</strong>：可比性的前提是接口统一、时间统一、判定确定，三者缺一分数就说明不了问题。用游戏内部状态而非视觉判断来验证任务完成，把评测误差从管线里去掉。重复完整重跑不是附录细节，而是交互式 benchmark 敢不敢让人比较相邻系统的前提。</p><p><strong>1 句话版</strong>：在闭环交互的评测里，把「接口、时间、判定」三样标准化，比再加十款游戏更有价值。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>Semantic Action Parsing 的语义动作空间对 34 款风格各异的游戏都是充分且中立的</strong>。整个双接口对比的解释力都建立在这上面——只有当语义动作空间既能表达每款游戏所需的全部操作，又不对任何一款游戏施加不成比例的先验，两条接口之间的分数差异才能被解释为「模型是否需要自己处理底层控制」。</p><p>它为什么可能不成立？动作空间的设计本身就是一种<strong>任务知识的注入</strong>。论文列出的语义动作是 <code>move_forward()</code>、<code>look_left()</code>、<code>action_jump()</code>、<code>weapon_fire()</code> 这种层级；但为一款平台跳跃游戏封装的「跳」和为 Monkey Mart 这类经营模拟封装的动作，其抽象层级不可能一致。抽象得越高，parser 替模型做的工作越多，语义接口的分数就越虚高，而这种偏差在不同游戏间是不均匀的，会污染跨游戏的聚合分。</p><p>论文提供的证据与反证都有。支持面：parser 是 <strong>deterministic</strong> 的，排除了解析器本身引入模型误差；action validity 分析里把 Out-of-Space 单列出来，等于在测「模型认为该有的动作和动作空间实际提供的动作差多少」；五级课程的雷达图显示两条接口形状高度相似，说明接口不是主导因素。反面证据来自作者自己的 Limitations：<strong>每个新环境都要单独设计指令集，动作空间与任务被紧耦合，这限制了可扩展性</strong>，并且作者把「用 MLLM 驱动的探索来自动生成并对齐 Semantic Action Parsing」列为未来工作。这句话等于承认动作空间目前是人工逐款设计的产物。</p><p>真正缺的关键证据是：<strong>每款游戏语义动作空间抽象层级的定量刻画，以及两接口分数差随该层级的变化曲线</strong>。论文报告了接口层面的聚合对比和逐游戏热力图，但没有把「这款游戏的语义封装做得多厚」量化出来，因此无法排除跨游戏聚合分被不均匀封装污染。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现 34 款游戏和 18 个组合。一周内可做的最小验证，直接针对 §9 的脆弱假设。</p><ul><li>选择 3 款操作模式差异最大的浏览器游戏（一款需要连续精确控制的、一款回合制的、一款需要快速反应的）。</li><li>对每款游戏，<strong>自己设计三套抽象层级不同的语义动作空间</strong>：低层（近似键鼠的封装，如「按住左键 200ms」）、中层（论文那一档，如 <code>move_forward()</code>、<code>action_jump()</code>）、高层（如「跳到下一个平台」「通过这一关的第一段」）。三套都实现为确定性 parser。</li><li>固定同一个 MLLM 与同一套四段式 prompt，沿用论文的 100 动作预算与暂停设置，在三套动作空间下各跑若干轮，同时也跑一遍原始键鼠接口。</li><li>测量三件事：任务进度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span>、Out-of-Space 无效动作率、以及 <strong><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 随抽象层级的斜率</strong>。</li><li>判据：如果 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 随抽象层级单调大幅上升，且不同游戏的上升幅度差异很大，说明语义接口的分数强烈依赖动作空间设计，跨游戏聚合分不能被解释为模型能力。若三套动作空间下 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 接近，则中立性假设站得住，论文的双接口对比是可靠的。</li></ul><p>这个实验不依赖论文的具体实现，只需要任意几款浏览器游戏和一个可调用的 MLLM，而它检验的正是论文在 Limitations 里承认尚未解决的那一项。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>反对者最有力的攻击针对**「实时交互是一个独立的、更难的挑战」这一结论**，因为论文自己的数字并不支持它。GameWorld-RT 上四个设置的成绩是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span></span></span></span> 15.6–17.1、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 32.9–34.0；而同样这两个 backbone 在暂停版的十次重跑里只有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mord mathcal">R</span></span></span></span></span> 12.5–13.8、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 30.1–30.9。<strong>不暂停反而分更高。</strong> 论文预先声明两者不可直接对比，理由是 RT 下同样的动作预算对应更长的游戏时长——但这个理由恰恰是问题所在：RT 变体同时改动了两件事（暴露延迟、放宽有效游戏时长），因此它无法把延迟的影响单独分离出来。「30B 快得多但分不更高」也不构成延迟无关紧要的反证，因为两个 backbone 的能力本来就不同。</p><p>一个干净得多的设计是<strong>在暂停版里注入受控延迟</strong>：保持一切不变，只在每次动作执行前人为等待 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord">Δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mclose">}</span></span></span></span> 秒的游戏时间，画出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span><span class="mopen">(</span><span class="mord">Δ</span><span class="mclose">)</span></span></span></span> 曲线，并按 genre 分开报告。如果 Runner 与 Arcade 的曲线陡降而 Puzzle 基本水平，「延迟是独立挑战」就被干净地证实；如果所有 genre 都平坦，那么 GameWorld-RT 测到的差异主要来自游戏时长而非反应速度。论文没有做这一项。</p><p>第二条攻击针对<strong>人类基线的统计基础</strong>。「远未达到人类水平」这个 headline 结论建立在<strong>两名计算机方向研究生</strong>身上，一人 Novice、一人 Expert，没有方差、没有逐游戏分布。更微妙的是动作预算的等价性：人类被限制 100 次原始动作（鼠标点击或按键），而智能体的每个动作在环境里执行一个固定时长（通常 200–500 ms）。在 Runner 这类游戏里，人类按住方向键持续输入与智能体发一次 <code>key_down</code> 后等 300 ms，二者的实际控制量并不对等，而这个不对等在不同 genre 上的方向可能相反。要让这条结论稳固，需要至少十名被试、报告分布而非单点，并额外报告一组「人类在与智能体完全相同的每步执行语义下」的成绩。</p><p>第三条针对<strong>长时程规划的覆盖度</strong>。引言把 long-horizon planning 列为核心考察目标之一，但五级课程里 Level 5（开放世界协调与管理）只有三款游戏（Fireboy and Watergirl、Minecraft Clone、Monkey Mart），且全局动作预算只有 100 步。这意味着 benchmark 的绝大部分质量落在百步以内可完成的任务上，而 Level 5 分数低这个观察，既可能是模型不会长时程规划，也可能只是 100 步不够用。案例研究里的 Minecraft Clone 恰好是这个歧义的样本：论文自己写它「推进到 90% 却在步数上限内没能完成」——这更像预算问题而非能力问题。检验方式很直接：报告 Expert Player 在 170 个任务上的实际完成步数分布，若 Level 5 任务的人类完成步数普遍逼近或超过 100，那么这一级的低分不能被解读为智能体的规划缺陷。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：本文把接口当作<strong>固定的实验条件</strong>（两选一），但真实的智能体使用场景里，接口层级本身是可以协商的——人类玩家也会在精细操作与调用高层技能之间切换。固定接口既掩盖了模型的适应能力，也让 §9 的动作空间偏差无法被自动纠正。作者在 Limitations 里承认了这条约束的代价（每接一个新环境都要人工设计指令集），并把「用 MLLM 驱动的探索自动生成并对齐 Semantic Action Parsing」列为未来工作——那是为了<strong>让 benchmark 更好扩展</strong>。下面这个 idea 走的是另一个方向：把同一件事变成<strong>被评测的对象</strong>。</p><p><strong>新 framing</strong>：把「动作抽象层级」从实验条件变成智能体自己要学的决策变量，即研究 <strong>agent-authored action abstraction</strong>——智能体在与游戏交互的过程中自行提出、命名并复用宏动作（macro-action），评测的对象从「在给定接口下的表现」变成「构造出多好的接口的能力」。可借鉴的相邻领域工具是分层强化学习中的 options framework 与程序合成里的 library learning（如 DreamCoder 式的抽象发现）：前者提供了何时终止一个宏动作的形式化，后者提供了从解题轨迹中归纳可复用抽象的机制。GameWorld 恰好为此提供了前提条件——统一的原子事件空间、确定性执行、以及从 gameAPI 读出的无噪声进度信号，后者可以直接当作抽象是否有用的判据。</p><p>这不是「扩展到更多游戏」式的增量工作，因为它把 benchmark 的度量对象从<strong>能力</strong>改成了<strong>元能力</strong>，并且顺带解决了动作空间中立性问题——如果抽象是智能体自己造的，它就不再是评测者注入的先验。</p><p><strong>第一个实验</strong>：在 GameWorld 的一个游戏子集上，给智能体一个只含最底层键鼠原语的初始接口，外加一个可写的宏动作库。智能体在每局结束后可以把成功片段封装成命名宏并加入库中，后续可直接调用。度量三件事：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span></span> 随库规模的增长曲线、库中宏动作在<strong>未见游戏</strong>上的复用率、以及自造接口与人工设计的 Semantic Action Parsing 之间的差距。如果自造抽象在同一游戏内快速追平人工接口，但跨游戏复用率很低，说明抽象发现可行但缺乏泛化机制，这本身就指出了下一个问题；如果跨游戏复用率不低，那么「通用游戏智能体」的路径就从「更强的单次决策」转向「更好的抽象积累」。这个实验还能顺带给出 §11 里那条长时程质疑的答案——宏动作等于把 100 步预算的有效长度撑开了。</p>',66)])])}const d=a(p,[["render",l]]);export{h as __pageData,d as default};
